			store.operator !== "=" ||
			!A.isSubNode(store.left) ||
			!A.isSymbolRefNode(store.left.object) ||
			store.left.object.definition !== copyDeclaration.id.definition ||
			!readsOffset(store.left.property, indexDefinition, start) ||
			!A.isSubNode(store.right) ||
			store.right.optional ||
			!readsVariable(store.right.object, argumentsDefinition) ||
			!readsVariable(store.right.property, indexDefinition) ||
			lengthDefinition.identifiers.length !== 1 ||
			indexDefinition.identifiers.length !== 1 ||
			A.isLabeledStatementNode(compressor.parent()) ||
			globalMayBeRebound(compressor)
